      points: ["M11 #1", "M11 #2", "M11 #3", "M11 #4", "M11 #5", "M11 #6", "M11 #7", "M11 #8", "M11 #9", "M11 #10", "M8 #11 center", "M8 #12", "M8 #13", "M8 #14", "M8 #15"],
